const items = $input.all().map((item) => item.json);

const groupedItems = items.reduce((acc, item) => {
  const category = item["Categoria*"].toUpperCase();
  const title = item["Titulo*"].toUpperCase();
  const description = item["DescripcionBreve*"];
  const amount = item["Precio*"];
  const size = item["Talla"].toUpperCase().trim();
  const color = item["Color"].toUpperCase().trim();
  const sku = item["SKU*"];
  const stock = item["Stock*"];

  if (!acc[category]) {
    acc[category] = { categoria: category, productos: [] };
  }

  let product = acc[category].productos.find((prod) => prod.titulo === title);

  if (!product) {
    product = { titulo: title, descripcion: description, precio: amount, stock: stock,
               coleccion: size !== "" ? "Talla" : color !== "" ? "Color" : "Unica",  skus: [] };
    acc[category].productos.push(product);
  }

  product.skus.push({ titulo:sku, valor: size !== "" ? size : color !== "" ? color : "Unica" });

  return acc;
}, {});

const result = Object.values(groupedItems);

return result.map((item) => ({ json: item }));

