const catalogoCambios = $('sanetiza catalogo principal').all();
const copiaSinCambios = $('sanetiza modifiaciones').all();

const reporte = [];

// Helper para convertir la estructura anidada en un Mapa de Productos para búsqueda rápida
const crearMapaProductos = (data) => {
  const mapa = {};
  data.forEach(cat => {
    cat.json.productos.forEach(prod => {
      mapa[prod.titulo] = prod;
    });
  });
  return mapa;
};

const mapaCopia = crearMapaProductos(copiaSinCambios);

// Recorrer el catálogo que tiene los posibles cambios
catalogoCambios.forEach(categoriaObj => {
  categoriaObj.json.productos.forEach(prodNuevo => {
    const tituloProd = prodNuevo.titulo;
    const prodViejo = mapaCopia[tituloProd];

    // --- CASO 1: PRODUCTO NO EXISTE (CREADO) ---
    if (!prodViejo) {
      prodNuevo.skus.forEach(sku => {
        reporte.push({
          producto: tituloProd,
          sku: sku.titulo,
          estado: "creado",
          modificaciones: []
        });
      });
      return;
    }

    // CASO 2: PRODUCTO EXISTE
    prodNuevo.skus.forEach(skuNuevo => {
      const skuId = skuNuevo.titulo;
      const skuViejo = prodViejo.skus.find(s => s.titulo === skuId);
      let modificaciones = [];

      // A. Comparar propiedades básicas del producto
      const camposBase = ['descripcion', 'precio', 'stock', 'coleccion'];
      camposBase.forEach(campo => {
        if (String(prodNuevo[campo]) !== String(prodViejo[campo])) {
          modificaciones.push({
            columna: campo.toUpperCase(),
            previous: prodViejo[campo],
            current: prodNuevo[campo]
          });
        }
      });

      // B. Comparar valores específicos del SKU (ej. el color/valor)
      if (skuViejo) {
        if (skuNuevo.valor !== skuViejo.valor) {
          modificaciones.push({
            columna: "VALOR_SKU",
            previous: skuViejo.valor,
            current: skuNuevo.valor
          });
        }

        // Si hubo cambios en base o en el SKU, marcar como actualizado
        if (modificaciones.length > 0) {
          reporte.push({
            producto: tituloProd,
            sku: skuId,
            estado: "actualizado",
            modificaciones: modificaciones
          });
        }
      } else {
        // C. SKU NUEVO dentro de un producto que ya existía
        reporte.push({
          producto: tituloProd,
          sku: skuId,
          estado: "creado",
          modificaciones: []
        });
      }
    });
  });
});

return reporte;

